import{_ as o,o as s,c as a,a as e}from"./chunks/framework.BPFk9-tb.js";const m=JSON.parse('{"title":"写作课作业-035","description":"","frontmatter":{"date":"2020-08-23T20:04:33","title":"写作课作业-035","categories":["写作","作业"],"tags":["写作","作业"]},"headers":[],"relativePath":"posts/homework/035.md","filePath":"posts/homework/035.md"}'),l={name:"posts/homework/035.md"};function n(r,t,p,c,u,d){return s(),a("div",null,[...t[0]||(t[0]=[e("blockquote",null,[e("p",null,"8.23写作课作业：结合自己生活和工作谈一谈对“等不起，输不起和赢不起”的理解，运用一个排比和递进。")],-1),e("p",null,"我对“等不起，输不起，赢不起”的理解是：等不起是基础不够好，输不起是保障不够足，赢不起是能力不够强。",-1),e("p",null,"如果把某个时间点达到一定的资金水平作为一个里程碑的话，有两个因素会影响这个时间的到来的快慢，一个是基数，一个是成长率。如果基数小或者成长率低，那就是基础不够好，如果两者都占了，那就是基础差。对于基础差的人来说，这个等待的过程是漫长的，这个成长的过程是痛苦的，这个积累的过程是微小的，也正因为如此，这个过程是容易被放弃的，那棵种下的种子还未发芽，就停止了灌溉。",-1),e("p",null,"《定投改变命运》里说，“把钱想象成一个熟鸡蛋的结构，蛋黄的部分，就是你的日常必需开销；蛋白的部分，就是你为了抵御风险而准备的储蓄；蛋壳的部分，才是你可以用来投资的钱，它可以在未来两个大周期之内绝不离开市场……”，而输不起的原因就是蛋清太薄了，甚至干脆没有，稍有意外就想着动用那薄薄的蛋壳。",-1),e("p",null,"我们知道投资运气成分很大的事情，那么“暴富”的那一天可能会突然来临，自己是否准备好就变得尤为重要。查理芒格说过“想要拥有一件事物的最好方法，就是让自己配得上它”。我们经常听说彩票中奖暴富而后又返贫的故事，而那些没有返贫的人和过得更好的人，共同的点是不会因中奖就放弃了工作，放弃了赚钱，放弃了成长，只图享乐。",-1),e("p",null,"对于我自己来说，基础差底子薄，就需要加倍的耐心，一步一步践行，需要经常鼓励自己，现在的努力是为了更好的自己，更好的未来，一切都是值得的。",-1)])])}const _=o(l,[["render",n]]);export{m as __pageData,_ as default};
